  assert.equal(accounting.usage.toolCalls,1);assert.equal(accounting.usage.inputTokens,7);assert.ok(accounting.usage.outputTokens>=3);assert.equal(rows[0]!.usage.input_tokens.known_lower_bound??rows[0]!.usage.input_tokens.value,'7');
  if(boundary==='model-failed'){assert.equal(rows[1]!.status,'unknown');assert.equal(accounting.usage.reservedOutputTokens,4096);assert.equal(audit.findLast(e=>e.toolOutcome)?.toolOutcome?.status,'completed');}
  else assert.notEqual(audit.findLast(e=>e.toolOutcome)?.toolOutcome?.modelOutput,'ready');
  if(boundary.startsWith('cancel-')){assert.ok(audit.some(e=>e.kind==='tool.finished'),'late settlement is an independent fact');assert.ok(audit.some(e=>e.toolOutcome?.status==='unknown'),'frozen UNKNOWN remains');}
